{
  "lines": [
    {
      "id": "repertoire.familiar",
      "tiers": [
        {
          "id": "repertoire.familiar:t1",
          "title": "Знакомство без бейджика",
          "phrase": "У тебя накопилось 2 упражнения, каждое выполнено минимум в 3 разные дня. Знакомство закреплено: можно без «а мы встречались?».",
          "imagePrompt": "One single circular convex achievement medallion filling the frame with a narrow background margin, a premium mobile-game collectible coin. Thick multilayer silver-gold metal rim, chunky silver outer bevel, polished gold inner bevel, tiny metal rivets. Inside the rim, a circular domed translucent warm-gold enamel-glass insert for common rarity. ONE large integrated raised symbol: an open atlas with thick blank pages and a rounded sculpted spine, nearly frontal with minimal perspective, occupying 65% of the inner circle. Simple bold relief, gentle warm-gold glow. Two small cascading stars in turquoise and coral sit entirely inside the medallion, subordinate to the atlas. White and icy-blue glossy highlights across the glass dome. Saturated stylized 3D game-icon render, crisp readable silhouette at 96px, dark almost uniform navy background. Establish a round coin silhouette and rim proportions consistent across all three tiers. No letters, numbers, inscriptions, logos, people, bodies, photographs, floating standalone objects, scenery, diorama, product photography, or objects outside the medallion.",
          "fishMarkup": "[pleased] У тебя накопилось 2 упражнения, каждое выполнено минимум в 3 разные дня. [playful] Знакомство закреплено: можно без «а мы встречались?».",
          "audioText": "У тебя накопилось 2 упражнения, каждое выполнено минимум в 3 разные дня. Знакомство закреплено: можно без «а мы встречались?»."
        },
        {
          "id": "repertoire.familiar:t2",
          "title": "Ключ от репертуара",
          "phrase": "Ты собрал 5 знакомых упражнений: у каждого — минимум 3 разных дня выполнения. Репертуар уже тянет на мини-гастроли.",
          "imagePrompt": "One single circular convex achievement medallion filling the frame with a narrow background margin, a premium mobile-game collectible coin. Preserve the same round silhouette and rim proportions as the other tiers. Thick multilayer silver-gold metal rim with a chunky silver outer bevel, polished gold inner bevel and tiny metal rivets. A circular domed translucent warm-gold enamel-glass insert signals common rarity. ONE large integrated raised symbol: a broad ornate key with a rounded bow, sculpted grooves and chunky teeth, set on a slight diagonal while viewed almost frontally, occupying 65% of the inner circle. Moderately richer layered relief and a slightly brighter warm-gold halo than tier one, without changing rarity or format. Three small cascading stars in sapphire, mint and coral remain entirely within the medallion and secondary to the key. White and icy-blue glossy highlights on the glass dome. Saturated stylized 3D game-icon render, bold shapes readable at 96px, dark almost uniform navy background. No letters, numbers, inscriptions, logos, people, bodies, photographs, separate floating objects, scenery, diorama, realistic product photography, or objects outside the medallion.",
          "fishMarkup": "[confident] Ты собрал <emphasis>5 знакомых упражнений</emphasis>: у каждого — минимум 3 разных дня выполнения. [playful] Репертуар уже тянет на мини-гастроли.",
          "audioText": "Ты собрал 5 знакомых упражнений: у каждого — минимум 3 разных дня выполнения. Репертуар уже тянет на мини-гастроли."
        },
        {
          "id": "repertoire.familiar:t3",
          "title": "Свой маршрут в атласе",
          "phrase": "Ты накопил 10 упражнений, выполненных минимум в 3 разные дня каждое. Атлас движений теперь здоровается первым.",
          "imagePrompt": "One single circular convex achievement medallion filling the frame with a narrow background margin, designed as a premium mobile-game collectible coin. Keep exactly the same round silhouette and rim proportions as the preceding tiers. Thick multilayer silver-gold metal rim, chunky silver outer bevel, polished gold inner bevel, tiny metal rivets. Circular domed translucent warm-gold enamel-glass insert, unmistakably common rarity. ONE large integrated raised symbol: a bold eight-point compass rose with broad sculpted points and a polished central boss, no directional labels, almost perfectly frontal with minimal perspective, occupying 68% of the inner circle. The richest relief of this three-tier line: stepped metal facets, fine decorative grooves and a fuller soft warm-gold glow, while retaining the same medal format and common palette. Three small cascading stars in turquoise, ruby and pale blue sit entirely inside the medallion, secondary to the compass rose. Strong white and icy-blue glossy glass highlights. Saturated stylized 3D game-icon render, highly legible at 96px, dark almost uniform navy background. No letters, numbers, inscriptions, logos, people, bodies, photographs, standalone floating objects, scenery, diorama, realistic product photography, or objects outside the medallion.",
          "fishMarkup": "[proud] Ты накопил <emphasis>10 упражнений</emphasis>, выполненных минимум в 3 разные дня каждое. [playful] Атлас движений теперь здоровается первым.",
          "audioText": "Ты накопил 10 упражнений, выполненных минимум в 3 разные дня каждое. Атлас движений теперь здоровается первым."
        }
      ]
    }
  ]
}
